#!/usr/bin/env bash
set -eo pipefail

# Occam Benchmark Suite Runner
# Executes the modern 50~200 statement fuzz benchmark suite (benchmarks/fuzz_corpus/)
# generated by benchmarks/tools/fuzz_generator.py and emits results to
# benchmarks/fuzz_benchmark_results.jsonl.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

cd "$ROOT_DIR"

python3 "$SCRIPT_DIR/fuzz_corpus/run_fuzz_benchmarks.py" "$@"
"$SCRIPT_DIR/report.sh" --summary
